import{_ as e,o as a,c as i,a4 as o}from"./chunks/framework.BBs01uty.js";const g=JSON.parse('{"title":"阶段 1：请求全链路（外到内地图）","description":"","frontmatter":{},"headers":[],"relativePath":"java-practice/01-run-and-trace-request.md","filePath":"java-practice/01-run-and-trace-request.md"}'),r={name:"java-practice/01-run-and-trace-request.md"};function d(l,t,n,s,c,p){return a(),i("div",null,[...t[0]||(t[0]=[o(`<h1 id="阶段-1-请求全链路-外到内地图" tabindex="-1">阶段 1：请求全链路（外到内地图） <a class="header-anchor" href="#阶段-1-请求全链路-外到内地图" aria-label="Permalink to &quot;阶段 1：请求全链路（外到内地图）&quot;">​</a></h1><blockquote><p><strong>目标</strong>：像看 Koa 中间件一样，先建立&quot;请求从外到内经过什么&quot;的完整地图，知道<strong>每个环节该打开哪个文件</strong>，再逐个读。</p><p><strong>前置</strong>：mall 已启动，<code>http://localhost:8080/swagger-ui/index.html</code> 可访问。</p></blockquote><h2 id="一、先建地图-spring-的-洋葱" tabindex="-1">一、先建地图：Spring 的&quot;洋葱&quot; <a class="header-anchor" href="#一、先建地图-spring-的-洋葱" aria-label="Permalink to &quot;一、先建地图：Spring 的&quot;洋葱&quot;&quot;">​</a></h2><p>你熟 Koa 的请求流是洋葱模型：<strong>请求从外到内</strong>穿过一层层中间件，到达 controller/service，响应再<strong>从内到外</strong>原路返回。</p><p>Spring Boot 的请求流是一样的结构，只是名字不同：</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[HTTP 请求&lt;br&gt;进 Tomcat] --&gt; B[过滤器链&lt;br&gt;Filter&lt;br&gt;含 JWT 过滤器]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt; C[DispatcherServlet&lt;br&gt;Spring MVC 分发器]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt; D[Controller&lt;br&gt;UmsAdminController]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D --&gt; E[Service&lt;br&gt;UmsAdminServiceImpl]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    E --&gt; F[Mapper 接口&lt;br&gt;+ XML SQL]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    F --&gt; G[(MySQL)]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    G -.响应原路返回.-&gt; A</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Koa</th><th>Spring Boot</th><th>你熟悉的操作</th></tr></thead><tbody><tr><td>中间件（app.use）</td><td><strong>Filter</strong>（过滤器）</td><td>请求进来第一道关卡</td></tr><tr><td>路由守卫 / Guard</td><td>过滤器里的鉴权</td><td>有没有 token、白名单</td></tr><tr><td>路由（@Controller）</td><td>Controller</td><td>收参数、分发给 service</td></tr><tr><td>Service</td><td>Service</td><td>业务逻辑（查库、校验、生成 token）</td></tr><tr><td>Repository/DAO</td><td><strong>Mapper + XML</strong></td><td>真正执行的 SQL</td></tr></tbody></table><p><strong>核心心智</strong>：读 Spring 代码的顺序 = <strong>从外到内</strong>：Filter → Controller → Service → Mapper → DB。和你看 Koa 先看中间件一个道理。</p><h2 id="二、全链路地图-7-个环节-每个环节看哪个文件" tabindex="-1">二、全链路地图：7 个环节，每个环节看哪个文件 <a class="header-anchor" href="#二、全链路地图-7-个环节-每个环节看哪个文件" aria-label="Permalink to &quot;二、全链路地图：7 个环节，每个环节看哪个文件&quot;">​</a></h2><p>以下按<strong>外到内</strong>排列，这就是你读代码的路线图：</p><table tabindex="0"><thead><tr><th>#</th><th>环节</th><th>打开这个文件</th><th>重点看什么</th></tr></thead><tbody><tr><td>1</td><td>过滤器链（最外）</td><td><code>mall-security/.../component/JwtAuthenticationTokenFilter.java</code></td><td>从请求头取 token、解析、塞用户</td></tr><tr><td>2</td><td>安全配置</td><td><code>mall-security/.../config/SecurityConfig.java</code> + <code>application.yml</code> 的 <code>secure.ignored.urls</code></td><td>过滤器怎么挂进链、哪些路径免鉴权</td></tr><tr><td>3</td><td>分发器</td><td>框架内置（DispatcherServlet），<strong>不用看</strong></td><td>只需知道：它把请求路由到 Controller</td></tr><tr><td>4</td><td>Controller</td><td><code>mall-admin/.../controller/UmsAdminController.java</code></td><td>路由注解、参数绑定、返回包装</td></tr><tr><td>5</td><td>Service</td><td><code>mall-admin/.../service/impl/UmsAdminServiceImpl.java</code></td><td><code>login()</code>：查用户→验密→生成 token→写日志</td></tr><tr><td>6</td><td>Mapper</td><td><code>mall-mbg/.../mapper/UmsAdminMapper.java</code> + <code>UmsAdminMapper.xml</code></td><td>接口方法 ↔ XML 里的 SQL</td></tr><tr><td>7</td><td>数据库</td><td>MySQL 的 <code>ums_admin</code> 表（DBeaver 看）</td><td>数据长什么样（密码是 BCrypt 密文）</td></tr></tbody></table><p><strong>对照你的 Koa 习惯</strong>：环节 1-2 = 中间件（先看这俩，就知道请求前后有些啥）；环节 4-5 = 路由 + 业务；环节 6-7 = 数据访问。</p><h2 id="三、每个环节读什么-详细" tabindex="-1">三、每个环节读什么（详细） <a class="header-anchor" href="#三、每个环节读什么-详细" aria-label="Permalink to &quot;三、每个环节读什么（详细）&quot;">​</a></h2><h3 id="环节-1-过滤器链-最外-对应-koa-中间件" tabindex="-1">环节 1：过滤器链（最外，对应 Koa 中间件） <a class="header-anchor" href="#环节-1-过滤器链-最外-对应-koa-中间件" aria-label="Permalink to &quot;环节 1：过滤器链（最外，对应 Koa 中间件）&quot;">​</a></h3><p>打开 <code>JwtAuthenticationTokenFilter.java</code>，方法 <code>doFilterInternal</code>：</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">String authHeader </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> request.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getHeader</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Authorization&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ① 从请求头取 token</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ② 去掉 &quot;Bearer &quot; 前缀 → ③ 解析 token 拿用户名 → ④ 查用户权限</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ⑤ 塞进 SecurityContextHolder（当前用户存这）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">filterChain.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">doFilter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(request, response);   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ⑥ 放行，交给下一层</span></span></code></pre></div><p><strong>问题</strong>：这个过滤器怎么挂进链的？→ 去环节 2 看 <code>SecurityConfig.java</code> 的 <code>addFilterBefore(...)</code>。</p><h3 id="环节-2-安全配置-白名单" tabindex="-1">环节 2：安全配置 + 白名单 <a class="header-anchor" href="#环节-2-安全配置-白名单" aria-label="Permalink to &quot;环节 2：安全配置 + 白名单&quot;">​</a></h3><p>打开 <code>SecurityConfig.java</code>（<code>mall-security</code>）：</p><ul><li><code>addFilterBefore(jwtAuthenticationTokenFilter, ...)</code> —— 把自定义过滤器插进链</li><li>白名单：<code>application.yml</code> 里 <code>secure.ignored.urls</code>，命中就 <code>permitAll()</code> 跳过鉴权（<code>/admin/login</code>、<code>/swagger-ui/</code>）</li></ul><p><strong>对应 Koa</strong>：<code>app.use(jwtMiddleware)</code> + 一个 <code>if (whitelist.includes(path)) return next()</code>。</p><h3 id="环节-4-controller" tabindex="-1">环节 4：Controller <a class="header-anchor" href="#环节-4-controller" aria-label="Permalink to &quot;环节 4：Controller&quot;">​</a></h3><p>打开 <code>UmsAdminController.java</code> 的 <code>login</code> 方法：</p><ul><li><code>@RequestMapping(&quot;/admin&quot;)</code> + 方法上的 <code>/login</code> → 路由</li><li><code>@RequestBody</code> → 请求体 JSON 反序列化成对象</li><li>方法体：<strong>调 service，包 CommonResult 返回</strong>（Controller 不做业务）</li></ul><h3 id="环节-5-service-重点" tabindex="-1">环节 5：Service（重点） <a class="header-anchor" href="#环节-5-service-重点" aria-label="Permalink to &quot;环节 5：Service（重点）&quot;">​</a></h3><p>打开 <code>UmsAdminServiceImpl.java</code> 的 <code>login()</code>（第 99 行）：</p><ul><li><code>loadUserByUsername()</code> 查用户（含密码密文）</li><li><code>passwordEncoder.matches()</code> 比对密码</li><li><code>jwtTokenUtil.generateToken()</code> 生成 token</li><li><code>insertLoginLog()</code> 写登录日志</li></ul><h3 id="环节-6-mapper-xml" tabindex="-1">环节 6：Mapper + XML <a class="header-anchor" href="#环节-6-mapper-xml" aria-label="Permalink to &quot;环节 6：Mapper + XML&quot;">​</a></h3><ul><li><code>UmsAdminMapper.java</code>：接口方法 <code>selectByExample(...)</code>（无实现类，MyBatis 动态代理）</li><li><code>UmsAdminMapper.xml</code>：搜 <code>selectByExample</code>，看真正的 SQL</li></ul><h3 id="环节-7-数据库" tabindex="-1">环节 7：数据库 <a class="header-anchor" href="#环节-7-数据库" aria-label="Permalink to &quot;环节 7：数据库&quot;">​</a></h3><p>DBeaver 打开 <code>ums_admin</code> 表，看 <code>admin</code> 行的密码是 <code>$2a$10$...</code>（BCrypt 密文）——呼应环节 5 的 <code>passwordEncoder.matches()</code>。</p><h2 id="四、用调试器-亲眼走一遍-洋葱-核心练习" tabindex="-1">四、用调试器&quot;亲眼走一遍&quot;洋葱（核心练习） <a class="header-anchor" href="#四、用调试器-亲眼走一遍-洋葱-核心练习" aria-label="Permalink to &quot;四、用调试器&quot;亲眼走一遍&quot;洋葱（核心练习）&quot;">​</a></h2><p>读十遍不如走一遍。按地图从外到内打 4 个断点：</p><table tabindex="0"><thead><tr><th>断点位置</th><th>对应环节</th></tr></thead><tbody><tr><td><code>JwtAuthenticationTokenFilter.doFilterInternal</code> 第 40 行</td><td>环节 1</td></tr><tr><td><code>UmsAdminController.login</code> 第 60 行</td><td>环节 4</td></tr><tr><td><code>UmsAdminServiceImpl.login</code> 第 99 行</td><td>环节 5</td></tr><tr><td><code>loadUserByUsername</code> 第 265 行</td><td>环节 5（查库前）</td></tr></tbody></table><p>步骤：</p><ol><li>IDEA 以 <strong>Debug</strong> 启动 <code>MallAdminApplication</code></li><li>打上上述 4 个断点</li><li>Swagger 调 <code>POST /admin/login</code></li><li>观察 IDEA 断点<strong>按环节 1 → 4 → 5 → 5 的顺序依次停住</strong>——这就是洋葱从外到内</li><li>每层停住时看 Variables 窗口：token 怎么来的、用户名怎么传下来的</li></ol><blockquote><p>这个练习做完，&quot;请求怎么走完&quot;就有了<strong>肌肉记忆</strong>，比看任何文章都管用。</p></blockquote><h2 id="五、验收标准-做完自检" tabindex="-1">五、验收标准（做完自检） <a class="header-anchor" href="#五、验收标准-做完自检" aria-label="Permalink to &quot;五、验收标准（做完自检）&quot;">​</a></h2><ul><li>[ ] 能画出 7 环节洋葱图（Filter → Controller → Service → Mapper → DB）</li><li>[ ] 能说出：登录请求在哪个环节被放行（白名单）、在哪个环节生成 token</li><li>[ ] 能说出 <code>userDetails.getPassword()</code> 拿到的是明文还是密文</li><li>[ ] 调试时 4 个断点按从外到内顺序依次停住</li></ul><h2 id="六、动手任务" tabindex="-1">六、动手任务 <a class="header-anchor" href="#六、动手任务" aria-label="Permalink to &quot;六、动手任务&quot;">​</a></h2><ol><li>按第四节把 4 个断点走一遍，记录每个断点停住时 Variables 里关键变量的值</li><li>用 Mermaid 画出&quot;登录请求&quot;的外到内链路图（放进你的笔记）</li><li>想挑战：给 <code>UmsAdminServiceImpl.login()</code> 里 <code>insertLoginLog</code> 打个断点，看响应怎么从内到外返回</li></ol><h2 id="七、常见问题" tabindex="-1">七、常见问题 <a class="header-anchor" href="#七、常见问题" aria-label="Permalink to &quot;七、常见问题&quot;">​</a></h2><p><strong>Q：为什么 Swagger 调登录时 <code>JwtAuthenticationTokenFilter</code> 没停？</strong> A：停了的，只是登录接口在白名单里，过滤器看到没带 token（或 token 无效）就直接放行了。断点如果打在 token 解析那几行会经过，打在白名单判断后可能跳过。</p><p><strong>Q：DispatcherServlet 要不要看？</strong> A：不用，那是框架核心（Spring MVC 的心脏），不是业务代码。知道&quot;它把 URL 路由到 Controller&quot;即可，以后有兴趣再深挖。</p><p><strong>Q：Koa 里响应也是洋葱逆序返回，Spring 也是吗？</strong> A：是的。响应从 MySQL → Mapper → Service → Controller → Filter 原路返回。调试时观察 <code>insertLoginLog</code> 之后继续 F8，能看到返程。</p><h2 id="八、关联理论" tabindex="-1">八、关联理论 <a class="header-anchor" href="#八、关联理论" aria-label="Permalink to &quot;八、关联理论&quot;">​</a></h2><ul><li><a href="/knowledge/service/spring-boot.html">Spring Boot 入门与实战</a> — Filter 过滤器链、Lombok、MyBatis 基础概念</li><li><a href="/knowledge/service/spring-principles.html">Spring 核心原理</a> — IoC、AOP、Spring MVC 分发</li><li><a href="/knowledge/service/auth.html">认证与授权</a> — JWT 原理</li></ul>`,47)])])}const u=e(r,[["render",d]]);export{g as __pageData,u as default};
